struct AuthMessageBuilder {
  typedef AuthMessage Table;
  ::flatbuffers::FlatBufferBuilder &fbb_;
  ::flatbuffers::uoffset_t start_;
  void add_protocol_version(uint16_t protocol_version) {
    fbb_.AddElement<uint16_t>(AuthMessage::VT_PROTOCOL_VERSION, protocol_version, 1);
  }
  void add_payload_type(Dnf::Protocol::Auth::AuthPayload payload_type) {
    fbb_.AddElement<uint8_t>(AuthMessage::VT_PAYLOAD_TYPE, static_cast<uint8_t>(payload_type), 0);
  }
  void add_payload(::flatbuffers::Offset<void> payload) {
    fbb_.AddOffset(AuthMessage::VT_PAYLOAD, payload);
  }
  explicit AuthMessageBuilder(::flatbuffers::FlatBufferBuilder &_fbb)
        : fbb_(_fbb) {
    start_ = fbb_.StartTable();
  }
  ::flatbuffers::Offset<AuthMessage> Finish() {
    const auto end = fbb_.EndTable(start_);
    auto o = ::flatbuffers::Offset<AuthMessage>(end);
    return o;
  }
};

inline ::flatbuffers::Offset<AuthMessage> CreateAuthMessage(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    uint16_t protocol_version = 1,
    Dnf::Protocol::Auth::AuthPayload payload_type = Dnf::Protocol::Auth::AuthPayload_NONE,
    ::flatbuffers::Offset<void> payload = 0) {
  AuthMessageBuilder builder_(_fbb);
  builder_.add_payload(payload);
  builder_.add_protocol_version(protocol_version);
  builder_.add_payload_type(payload_type);
  return builder_.Finish();
}

template <bool B>
inline bool VerifyAuthPayload(::flatbuffers::VerifierTemplate<B> &verifier, const void *obj, AuthPayload type) {
  switch (type) {
    case AuthPayload_NONE: {
      return true;
    }
    case AuthPayload_LoginRequest: {
      auto ptr = reinterpret_cast<const Dnf::Protocol::Auth::LoginRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case AuthPayload_CharacterListRequest: {
      auto ptr = reinterpret_cast<const Dnf::Protocol::Auth::CharacterListRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case AuthPayload_CharacterSelectionRequest: {
      auto ptr = reinterpret_cast<const Dnf::Protocol::Auth::CharacterSelectionRequest *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case AuthPayload_LoginResponse: {
      auto ptr = reinterpret_cast<const Dnf::Protocol::Auth::LoginResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case AuthPayload_CharacterListResponse: {
      auto ptr = reinterpret_cast<const Dnf::Protocol::Auth::CharacterListResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case AuthPayload_CharacterSelectionResponse: {
      auto ptr = reinterpret_cast<const Dnf::Protocol::Auth::CharacterSelectionResponse *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

template <bool B>
inline bool VerifyAuthPayloadVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyAuthPayload(
        verifier,  values->Get(i), types->GetEnum<AuthPayload>(i))) {
      return false;
    }
  }
  return true;
}

